function segmentText(text) {
  if (typeof text !== 'string' || !text.trim()) throw new Error('O texto está vazio.');
  if (typeof Intl.Segmenter !== 'function') throw new Error('Este ambiente não oferece segmentação de frases.');
  const maxWords = 50;
  const segments = [];
  for (const part of new Intl.Segmenter('pt-BR', { granularity: 'sentence' }).segment(text)) {
    const words = [...part.segment.matchAll(/\S+/gu)];
    if (!words.length) continue;
    // Long unpunctuated passages need deterministic anchors, not invented sentences.
    const chunkCount = Math.ceil(words.length / maxWords);
    const chunkSize = Math.ceil(words.length / chunkCount);
    for (let i = 0; i < words.length; i += chunkSize) {
      const next = i + chunkSize;
      segments.push({
        id: `SEG_${String(segments.length + 1).padStart(5, '0')}`,
        start: part.index + (i === 0 ? 0 : words[i].index),
        end: next < words.length ? part.index + words[next].index : part.index + part.segment.length,
      });
    }
  }
  return {
    version: 'sentence-pt-BR-v2', locale: 'pt-BR', offsetUnit: 'utf16',
    strategy: 'sentences-with-word-fallback', maxWordsPerSegment: maxWords, segments,
  };
}
function validateSegmentSource(text, segmentedText, segmentation) {
  if (typeof text !== 'string' || !text.trim() || segmentation?.offsetUnit !== 'utf16'
    || !Array.isArray(segmentation.segments) || !segmentation.segments.length) throw new Error('Texto ou mapa de segmentos inválido.');
  let lastEnd=0;
  for (const [i,s] of segmentation.segments.entries()) {
    if (s?.id !== `SEG_${String(i+1).padStart(5,'0')}` || !Number.isInteger(s.start) || !Number.isInteger(s.end)
      || s.start<lastEnd || s.end<=s.start || s.end>text.length
      || text.slice(lastEnd,s.start).trim() || !text.slice(s.start,s.end).trim()) throw new Error('Segmento inválido: '+(s?.id??i));
    lastEnd=s.end;
  }
  if (text.slice(lastEnd).trim()) throw new Error('Mapa de segmentos perdeu conteúdo do original.');
  const expected=segmentation.segments.map(s=>`[${s.id}] ${text.slice(s.start,s.end).trim()}`).join('\n');
  if (segmentedText!==expected) throw new Error('Texto segmentado diverge do original e do mapa.');
  return segmentation;
}
