function prepareAspectActions(context) {
  const keys = ['victory', 'obstacle', 'story', 'gratitude', 'joke', 'personalLife'];
  if (keys.some(key => typeof context?.aspects?.flags?.[key] !== 'boolean')) throw new Error('Aspectos inválidos para roteamento.');
  const active = keys.filter(key => context.aspects.flags[key]);
  return (active.length ? active : ['none']).map(aspect => ({ ...context, flags: context.aspects.flags, aspect }));
}
return prepareAspectActions($input.first().json).map(json=>({json,pairedItem:{item:0}}));

return $input.all().map((item, index) => {
  const context = $('Preparar ações dos aspectos true').itemMatching(index).json;
  const result = item.json;
  return {json:{...context,...result,aspect:context.aspect,errors:{...context.errors,...result.errors}},pairedItem:{item:index}};
});

function combineFinalization(items) {
  if (!items.length || !items[0].aspects) throw new Error('Finalização sem resultados de aspectos.');
  const first = items[0];
  const errors = Object.assign({}, ...items.map(item => item.errors ?? {}));
  const victory = items.find(item => item.aspect === 'victory');
  return { ok: true, contentDecisions:first.contentDecisions??[], generatedContents:first.generatedContents??[], generatedContentErrors:first.generatedContentErrors??[], aspects: first.aspects, diary: first.diary ?? null,
    achievements: victory?.achievements ?? [], errors,
    activeRoutes: Object.keys(first.aspects.flags).filter(key => first.aspects.flags[key]),
    actionResults: items.filter(item => item.aspect !== 'none').map(item => ({ aspect: item.aspect, status: item.errors?.brag && item.aspect === 'victory' ? 'failed' : item.aspect === 'victory' ? 'completed' : 'no_behavior' })) };
}
// Cada caminho registra seu resultado. Só o último a concluir emite o retorno.
const context = $('Validar título e resumo').first().json;
const active = Object.keys(context.aspects.flags).filter(key => context.aspects.flags[key]);
const expected = active.length ? active : ['none'];
const completed = new Map();
let lastAspect;
for (let run = 0; run < expected.length; run++) {
  let items;
  try { items = $('Registrar resultado da ação').all(0, run); } catch { break; }
  for (const item of items) {
    if (expected.includes(item.json.aspect)) {
      completed.set(item.json.aspect, item.json);
      lastAspect = item.json.aspect;
    }
  }
}
if (expected.some(aspect => !completed.has(aspect))) return [];
// Evita resposta duplicada mesmo se o n8n enfileirar a montagem dos ramos juntos.
if (!$input.all().some(item => item.json.aspect === lastAspect)) return [];
return [{json:combineFinalization(expected.map(aspect => completed.get(aspect)))}];
